function flightScoreKey(){return mode==='camera'&&cameraControl==='body'?'body':mode}
const flight=new FlightEngine();let flightPaused=false,flightWasValid=false;
const flightSessions={practice:{score:0,count:0},camera:{score:0,count:0},body:{score:0,count:0}};
let flightSaved={practice:{best:0,history:[]},camera:{best:0,history:[]},body:{best:0,history:[]}},flightStorage=true;
try{const saved=JSON.parse(localStorage.getItem('little-lungs-flight-v2')||'null');for(const m of ['practice','camera','body'])if(saved?.[m]){flightSaved[m].best=Number.isSafeInteger(saved[m].best)&&saved[m].best>=0?saved[m].best:0;flightSaved[m].history=Array.isArray(saved[m].history)?saved[m].history.filter(v=>Number.isInteger(v)&&v>=0&&v<=30).slice(0,10):[]}}catch{flightStorage=false}
const flightBoard=document.createElement('section');flightBoard.id='flightBoard';flightBoard.innerHTML='<div class="boardTitle"><div><span class="eyebrow">EVERY LANDING IS A LITTLE WIN</span><h2>Balloon scoreboard</h2></div><span id="flightMode"></span></div><div class="scoreStats"><div><strong id="flightScore">0</strong><span>POINTS THIS ROUND</span></div><div><strong id="flightCount">0</strong><span>COMPLETED FLIGHTS</span></div><div><strong id="flightBest">0</strong><span>BEST ROUND ON THIS DEVICE</span></div></div><p>Start on the meadow. Wave to rise and stay still to land in Body movement mode. With Spirometer balls selected, the balloon follows the highest ball and lands when all three are down. Touch the moving diamonds for 2, 5, and 8 points. An occasional gold diamond triggered by a rising green spirometer ball gives 15 points. Landing adds no extra points.</p><div class="boardActions"><button id="pauseFlight">Pause</button><button id="newFlight">New round</button></div><h3>Recent flights</h3><ol id="flightHistory"></ol><button id="clearFlights">Clear saved balloon scores</button><p class="hint" id="flightStorage">Only game points are saved in this browser. Body camera, spirometer camera, and practice scores stay separate. Follow your prescribed routine. No need to chase a diamond or breathe harder.</p>';document.querySelector('.bottom').before(flightBoard);
const pad=document.createElement('div');pad.className='landingPad';pad.textContent='✧';gameSection.append(pad);
function updateFlightBoard(){const session=flightSessions[flightScoreKey()],saved=flightSaved[flightScoreKey()];$('flightMode').textContent=mode==='camera'?'Camera · experimental':'Practice · simulated';$('flightScore').textContent=session.score;$('flightCount').textContent=session.count;$('flightBest').textContent=Math.max(saved.best,session.score);$('flightHistory').replaceChildren(...(saved.history.length?saved.history.map((n,i)=>Object.assign(document.createElement('li'),{textContent:`Landing ${saved.history.length-i} · +${n} points`})): [Object.assign(document.createElement('li'),{textContent:'Your first landing is waiting.'})]));if(game==='balloon')$('stars').textContent=`★ ${session.score} pts`;if(!flightStorage)$('flightStorage').textContent='Browser storage is unavailable. Scores last only while this page stays open.'}
function saveFlights(){try{localStorage.setItem('little-lungs-flight-v2',JSON.stringify(flightSaved))}catch{flightStorage=false}}
function resetFlightMotion(){flight.reset();flightPaused=false;flightWasValid=false;$('pauseFlight').textContent='Pause';$('balloon').style.bottom='82px';$('balloon').classList.remove('landingGlow');}
function syncFlightGame(){flightBoard.hidden=game!=='balloon';gameSection.classList.toggle('balloonScene',game==='balloon');resetFlightMotion();if(game==='balloon'){updateFlightBoard();$('float').textContent='Hold to rise · release to land';document.querySelector('#practicePanel .center').innerHTML='Hold to help the balloon rise.<br>Release to make it glow and land.';say(mode==='camera'?'Calibrate the balls, then start on the meadow.':'Start on the meadow. Hold to rise, release to land.')}}
function balloonFrame(input,dt,valid){
 if(game!=='balloon')return;
 const blocked=flightPaused||$('help').open||document.hidden;
 const levels=mode==='camera'?trackedLevels:[input,input,input];
 gameSection.style.setProperty('--body-sway',mode==='camera'&&cameraControl==='body'?bodySway+'px':'0px');
 const result=flight.step(levels,dt,valid,blocked);
 if(typeof updateSky==='function')updateSky(result.height,dt,valid&&!blocked);
 if(valid&&!blocked){$('balloon').style.bottom=`${82+result.height*Math.max(60,Math.min(180,gameSection.clientHeight-332))}px`;$('balloon').classList.toggle('landingGlow',result.glow)}else $('balloon').classList.remove('landingGlow');
 if(typeof diamondFrame==='function')diamondFrame(result,dt,valid&&!blocked);
 if(result.landed){const session=flightSessions[flightScoreKey()],saved=flightSaved[flightScoreKey()];session.count++;saved.best=Math.max(saved.best,session.score);saved.history.unshift(diamondFlight.flightPoints);saved.history=saved.history.slice(0,10);saveFlights();updateFlightBoard();say('A glowing landing! '+diamondFlight.flightPoints+' points this flight. Take your time.');}
 else if(!blocked&&valid&&result.phase==='flying')say(mode==='camera'&&cameraControl==='body'?'Up we go! Move gently, then stay still to land.':'Up we go! Follow your usual routine.');
 else if(!blocked&&valid&&result.phase==='ground')say('On the meadow. Ready whenever you are.');
 else if(!blocked&&!valid&&mode==='camera'&&flightWasValid)say(cameraControl==='body'?'Motion paused. Check lighting and camera. No points added.':'Tracking paused. Check all three balls. No points added.');
 flightWasValid=valid&&!blocked;
}
for(const id of ['balloonGame','mineGame','practice','camera']){const previous=$(id).onclick;$(id).onclick=()=>{previous();syncFlightGame()}}
$('pauseFlight').onclick=()=>{flightPaused=!flightPaused;held=false;flight.reset();$('pauseFlight').textContent=flightPaused?'Resume':'Pause';say(flightPaused?'Paused. Take a comfortable break.':'Ready whenever you are. Let the balls rest first.')};
$('newFlight').onclick=()=>{flightSessions[flightScoreKey()]={score:0,count:0};resetFlightMotion();updateFlightBoard();say('A fresh flight. Start with the balls at rest.')};
$('clearFlights').onclick=()=>{flightSaved={practice:{best:0,history:[]},camera:{best:0,history:[]},body:{best:0,history:[]}};flightSessions.practice={score:0,count:0};flightSessions.camera={score:0,count:0};flightSessions.body={score:0,count:0};resetFlightMotion();saveFlights();updateFlightBoard()};
syncFlightGame();
